"""Exact residual-prime separation for p17 total order 14, split (7,7)."""
from collections import Counter, defaultdict
from fractions import Fraction
from functools import lru_cache
from itertools import combinations
import json

P = 17
BUDGET = 2331
LOW_PRIMES = (13, 11, 7, 5, 3, 2)
MOD = tuple(P**k for k in range(1,4))


def smooth(n):
    for prime in LOW_PRIMES:
        while n % prime == 0:
            n //= prime
    return n == 1


def valuation(n, prime):
    v = 0
    while n % prime == 0:
        n //= prime
        v += 1
    return v


def atoms():
    return tuple(
        (q, P*q+r, P*(P*q+r)-1)
        for q in range(7,-1,-1) for r in range(1,P)
        if P*(P*q+r)-1 <= BUDGET and smooth(P*q+r)
    )


def add(a, b, moduli):
    return tuple((x+y) % m for x,y,m in zip(a,b,moduli))


def side_states(rows):
    """Descending q puts all q0 atoms after the last positive-order choice."""
    residues = [tuple(pow(m,-k,mod) for k,mod in enumerate(MOD,1)) for _,m,_ in rows]

    def visit(start, order, remaining, choices, mask, signature):
        if order == 0:
            yield choices, mask, remaining, signature
        for i in range(start,len(rows)):
            q,m,cost = rows[i]
            if q == 0 and order > 0:
                break
            if q <= order and cost <= remaining:
                yield from visit(i,order-q,remaining-cost,(*choices,m),
                                 mask | (1<<i),add(signature,residues[i],MOD))

    return visit(0,7,BUDGET,(),0,(0,0,0))


def disjoint_vertical_count(rows):
    """Signed coefficients of ∏(1-x^q y^cost) implement inclusion-exclusion."""
    f = [[0]*(BUDGET+1) for _ in range(8)]
    coeff = [[0]*(BUDGET+1) for _ in range(8)]
    f[0][0] = coeff[0][0] = 1
    for q,_,cost in rows:
        if not q:
            continue
        for n in range(q,8):
            for c in range(cost,BUDGET+1):
                f[n][c] += f[n-q][c-cost]
        for n in range(7,q-1,-1):
            for c in range(BUDGET,cost-1,-1):
                coeff[n][c] -= coeff[n-q][c-cost]
    for row in f:
        for c in range(1,BUDGET+1):
            row[c] += row[c-1]
    ordered = sum(
        k*f[7-q][BUDGET-c]**2
        for q,row in enumerate(coeff) for c,k in enumerate(row) if k
    )
    assert ordered % 2 == 0
    return f[7][-1], ordered//2


def square_profiles():
    """High-valuation cancellation using S1,S2,S3, independently counted."""
    seen = set()
    states = 0

    def visit(start, remaining, values):
        nonlocal states
        assert values not in seen
        states += 1
        seen.add(values)
        for j in range(start,9):
            cost = P*P*j-1
            if cost <= remaining:
                phase = tuple(pow(j,-k,P) for k in (1,2,3))
                visit(j,remaining-cost,add(values,phase,(P,P,P)))

    visit(1,BUDGET,(0,0,0))
    assert states == 67
    return states


def difference(u, v):
    return tuple(
        sum(Fraction(1,(P*m)**k) for m in u) -
        sum(Fraction(1,(P*m)**k) for m in v)
        for k in range(1,4)
    )


def pairs(rows):
    groups = defaultdict(list)
    for u,mask,budget,key in side_states(rows):
        groups[key].append((u,mask,budget))
    out = []
    matching = 0
    for key, entries in groups.items():
        matching += len(entries)*(len(entries)-1)//2
        for a,b in combinations(entries,2):
            if not a[1] & b[1]:
                (u,_,A),(v,_,B) = sorted((a,b))
                out.append((u,v,A,B,key))
    assert (sum(map(len,groups.values())),matching,len(out)) == (55347,1850,27)
    return sorted(out)


@lru_cache(maxsize=None)
def tail_states(budget, prime, max_valuation):
    """Generate q-divisible atoms only; compare DFS to geometric-series DP."""
    moduli = tuple(prime**(k*max_valuation) for k in (1,2,3))
    options = []
    for a in range(prime,budget+2,prime):
        if a % 17 == 0:
            continue
        exponent = valuation(a,prime)
        unit = a//prime**exponent
        phase = tuple(
            prime**(k*(max_valuation-exponent))*pow(unit,-k,mod) % mod
            for k,mod in enumerate(moduli,1)
        )
        options.append((a-1,phase))

    seen = set()
    states = 0

    def visit(start, remaining, signature):
        nonlocal states
        states += 1
        seen.add(signature)
        for i in range(start,len(options)):
            cost,phase = options[i]
            if cost > remaining:
                break
            visit(i,remaining-cost,add(signature,phase,moduli))

    visit(0,budget,(0,0,0))
    dp = [set() for _ in range(budget+1)]
    dp[0].add((0,0,0))
    for cost,phase in options:
        for mass in range(cost,budget+1):
            dp[mass].update(add(x,phase,moduli) for x in dp[mass-cost])
    assert seen == set().union(*dp)
    return seen, states, moduli


def tail_obstruction(delta, A, B, prime):
    m = 0
    while prime**(m+1) <= max(A,B)+1:
        m += 1
    mods = tuple(prime**(k*m) for k in (1,2,3))
    targets = tuple(-x*mod for x,mod in zip(delta,mods))
    bad = tuple(k for k,y in enumerate(targets,1) if y.denominator%prime == 0)
    if bad:
        return {"prime":prime,"height":m,"type":"target_denominator","failed_moments":bad}
    if not m:
        return None
    a, raw_a, mods = tail_states(A,prime,m)
    b, raw_b, _ = tail_states(B,prime,m)
    want = tuple(y.numerator*pow(y.denominator,-1,mod)%mod
                 for y,mod in zip(targets,mods))
    if all(add(want,r,mods) not in a for r in b):
        return {"prime":prime,"height":m,"type":"incompatible_residues","moduli":mods,
                "residual_target":want,"raw_tail_profiles":(raw_a,raw_b),
                "distinct_tail_residues":(len(a),len(b))}
    return None


def main():
    rows = atoms()
    profile_counts = disjoint_vertical_count(rows)
    assert profile_counts == (1907,809566)
    certificates=[]
    census=Counter()
    for u,v,A,B,signature in pairs(rows):
        delta = difference(u,v)
        obstruction = None
        for prime in (13,11,7):
            obstruction = tail_obstruction(delta,A,B,prime)
            if obstruction:
                break
        assert obstruction is not None
        census[prime]+=1
        certificates.append({
            "cofactors": (u,v), "tail_budgets":(A,B), "q17_signature":signature,
            "delta_reciprocal_moments":tuple(map(str,delta)),
            "obstruction":obstruction,
        })
    assert census == {13:17,11:7,7:3}
    print(json.dumps({"square_profiles":square_profiles(),"vertical_profiles":profile_counts[0],
                      "vertical_disjoint_pairs":profile_counts[1],"complete_once_17_sides":55347,
                      "three_moment_disjoint_candidates":len(certificates),
                      "first_excluding_prime":census,"certificates":certificates},
                     indent=2,sort_keys=True))


if __name__=="__main__":
    main()

