"""Exploratory necessary cuts for equality of H0,H1,H2 at the same split."""
from collections import Counter, defaultdict
from fractions import Fraction
from functools import lru_cache
from itertools import combinations
from pathlib import Path
import json

from replay import P, atoms, side_states, smooth, valuation

def expand(poly, a):
    return sum(Fraction(c,a**k) for k,c in enumerate(poly))

def target(v, p, height, degree):
    mod=p**(height*degree)
    scaled=v*mod
    assert scaled.denominator%p
    return scaled.numerator*pow(scaled.denominator,-1,mod)%mod

P_ORDER=(13,11,7,5)
F=((1,), (0,1), (0,0,1), (1,-2), (0,1,-2), (1,-5,6))

@lru_cache(maxsize=None)
def cap(F,B):
    vals=[Fraction()] + [expand(F,a)/(a-1) for a in range(2,B+2) if smooth(a)]
    return min(vals),max(vals)

def cut(w,A,B):
    for F1 in F:
        value=sum(x*y for x,y in zip(w,F1))
        A_min,A_max=cap(F1,A)
        B_min,B_max=cap(F1,B)
        if value>B*B_max-A*A_min or value<B*B_min-A*A_max:
            return True
    return False

@lru_cache(maxsize=None)
def local(prime,m):
    mods=(prime**m,prime**(2*m))
    candidates=[]
    for a in range(prime,294,prime):
        if not smooth(a): continue
        v=valuation(a,prime)
        if v>m: continue
        unit=a//prime**v
        candidates.append((a-1,*(prime**(i*(m-v))*pow(unit,-i,n)%n for i,n in enumerate(mods,1))))
    mass={}
    def gen(j,c,r,s):
        key=r,s
        if c<mass.get(key,293): mass[key]=c
        for i in range(j,len(candidates)):
            cost,d,e=candidates[i]
            if c+cost>292: break
            gen(i,c+cost,(r+d)%mods[0],(s+e)%mods[1])
    gen(0,0,0,0)
    return mass,sorted((c,x,y) for (x,y),c in mass.items()),mods

def ptest(w,A,B,p):
    m=0
    while p**(m+1)<=max(A,B)+1:
        m+=1
    if any(valuation(w[k].denominator,p)>k*m for k in (1,2)):
        return True
    if not m: return False
    if B>A:
        A,B=B,A
        w=tuple(-x for x in w)
    r,s=(target(w[k],p,m,k) for k in (1,2))
    d,a,mn=local(p,m)
    for c,x,y in a:
        if c>B: break
        if d.get(((x+r)%mn[0],(y+s)%mn[1]),293)<=A:
            return False
    return True

if __name__=='__main__':
    roots=atoms()
    sig_atom={m:(Fraction(1),Fraction(1,P*m),Fraction(1,(P*m)**2)) for q,m,w in roots}
    G=defaultdict(list)
    phases=Counter()
    for U,mask,A,key in side_states(roots):
        g=(len(U), *(sum(sig_atom[m][k] for m in U) for k in [1,2]))
        G[key[:2]].append((U,mask,A,g))
    left=[]
    for states in G.values():
        for (U,um,A,x),(V,vm,B,y) in combinations(states,2):
            if um&vm:continue
            phases['disjoint']+=1
            delta=tuple(a-b for a,b in zip(x,y))
            if cut(delta,A,B):
                phases['polynomial']+=1
                continue
            w=tuple(-x for x in delta)
            for prime in P_ORDER:
                if ptest(w,A,B,prime):
                    phases[str(prime)]+=1
                    break
            else:
                left.append([U,V,A,B,[str(t) for t in w]])
    print(json.dumps({"screen":phases,"remaining":len(left)},sort_keys=True))
    Path('order2-left.json').write_text(json.dumps(left,indent=2)+'\n')

