from math import lcm
from collections import defaultdict
from fractions import Fraction
from pathlib import Path
import json,sys
from replay import smooth, P, BUDGET

def mass(v):
    return sum(a-1 for a in v)

def stats(v,degree=3):
    return tuple(sum(Fraction(1,a**k) for a in v) for k in range(degree+1))

def find(caps,records):
    atoms=[a for a in range(2,caps+2) if smooth(a)]
    common=lcm(*atoms)
    base={a:(common//a,(common//a)**2) for a in atoms}
    minimum={}
    def dfs(i,left,v,h1,h2):
        key=len(v),h1,h2
        cost=caps-left
        if minimum.get(key,(caps+1,))[0]>cost:
            minimum[key]=(cost,v)
        for j in range(i,len(atoms)):
            a=atoms[j]
            if a-1>left: break
            x,y=base[a]
            dfs(j,left-(a-1),(*v,a),h1+x,h2+y)
    dfs(0,caps,(),0,0)
    rows=sorted((y[0],*x) for x,y in minimum.items())
    count=0
    for l,r,A,B,d in records:
        if max(A,B)>caps: continue
        count+=1
        target=tuple(Fraction(x)*common**k for k,x in enumerate(d))
        if any(x.denominator != 1 for x in target):continue
        x,y,z=map(int,target)
        flipped=A<B
        if flipped:
            A,B=B,A
            x,y,z=-x,-y,-z
        for cost,h0,h1,h2 in rows:
            if cost>B: break
            look=(h0+x,h1+y,h2+z)
            opt=minimum.get(look)
            if opt and opt[0]<=A:
                a,b=opt[1],minimum[h0,h1,h2][1]
                if flipped: a,b=b,a
                lhs=tuple(sorted([*a,*[P*m for m in l]]))
                rhs=tuple(sorted([*b,*[P*m for m in r]]))
                m1,m2=mass(lhs),mass(rhs)
                L,R=stats(lhs),stats(rhs)
                assert m1<=BUDGET and m2<=BUDGET and L[:3]==R[:3]
                print('FOUND',l,r,a,b,m1,m2,tuple(str(v) for v in L),tuple(str(v) for v in R),flush=True)
                return {"left":lhs,"right":rhs,"left_tail":a,"right_tail":b,
                        "mass":(m1,m2),"left_moments":[str(x) for x in L],"right_moments":[str(x) for x in R]}
    print(json.dumps({"exact_tail_cap":caps,"pairs_checked":count,"distinct_tail_keys":len(rows),"witness":None},sort_keys=True))
    return None

if __name__=='__main__':
    records=json.loads(Path('order2-left.json').read_text())
    result=find(int(sys.argv[1]),records)
    if result:
        Path('sharp-witness.json').write_text(json.dumps(result,indent=2)+'\n')
